// @ts-check
/**
 * Checks that every source file is named in kebab-case, with dot-separated role suffixes
 * (`create-customer.use-case.ts`, `customers.routes.ts`, `tsconfig.build.json`). CLAUDE.md "Nombres".
 * Usage: node scripts/check-filenames.mjs
 */
import { basename } from 'node:path';
import { pathToFileURL } from 'node:url';

import { listRepoFiles } from './lib/repo.mjs';

const CHECKED_ROOTS = ['apps/', 'packages/', 'tools/', 'scripts/', 'e2e/'];
/** Generated by drizzle-kit with its own names (`0000_brave_name.sql`, `meta/_journal.json`). */
const GENERATED_ROOTS = ['apps/api/drizzle/'];
const ALLOWED_NAMES = new Set(['README.md', 'Dockerfile']);
const SEGMENT = '[a-z0-9]+(?:-[a-z0-9]+)*';
const KEBAB_FILE = new RegExp(`^\\.?${SEGMENT}(?:\\.${SEGMENT})*$`);
const TEMPORARY_TEST_FILE = /^__(lint|cycle)_fixture__/;

/**
 * @param {readonly string[]} paths repository-relative paths with forward slashes
 * @returns {string[]} the paths whose file name breaks the convention
 */
export function findBadFileNames(paths) {
  return paths.filter((path) => {
    const isChecked = CHECKED_ROOTS.some((root) => path.startsWith(root));
    if (!isChecked || GENERATED_ROOTS.some((root) => path.startsWith(root))) return false;
    const name = basename(path);
    return !ALLOWED_NAMES.has(name) && !TEMPORARY_TEST_FILE.test(name) && !KEBAB_FILE.test(name);
  });
}

function main() {
  const offenders = findBadFileNames(listRepoFiles());
  if (offenders.length > 0) {
    process.stderr.write(
      `File names must be kebab-case (CLAUDE.md):\n${offenders.map((p) => `  - ${p}`).join('\n')}\n`,
    );
    process.exit(1);
  }
  process.stdout.write('check-filenames: OK\n');
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? '').href) main();
